let numinovals = 10;
let iterations = 6;
let scale = 0.5;
let offset = 0.5;

function setup() {
  createCanvas(600, 600, WEBGL);
  noStroke();
  colorMode(HSB, 360, 100, 100);
  fill(0, 0, 100);
}

function draw() {
  background(0, 0, 0);

  translate(0, 0, 150);

  for (let i = 0; i < numinovals; i++) {
    let angle = i * TWO_PI / numinovals;
    let x = cos(angle);
    let y = sin(angle);

    push();
    translate(x * scale, y * scale, 0);

    heartIteration(x, y, 0.5, 0.1, iterations);
    pop();
  }
}

function heartIteration(x, y, s, d, i) {
  if (i == 0) return;

  let nxy = x + y * 0.5;
  let np = nxy * 0.5;

  let nx = s * (x * 0.5 - y * 0.7);
  let ny = s * (y * 0.5 + x * 0.7);

  push();
  translate(nx, ny, 0);

  box(d);

  pop();

  heartIteration(nx, ny, s * 0.7, d * 0.6, i - 1);

  heartIteration(nxy, np, s * 0.7, d * 0.6, i - 1);
}
```

