class HelloWorldServer
{
    static void Main(string[] args)
    {
        // Crée un objet HttpListener
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/"); // Ajoute une plage d'URLs à écouter

        // Démarrer le serveur
        listener.Start();

        Console.WriteLine("Serveur démarré. Attend les requêtes...");

        while (true)
        {
            // Attendez une requête
            HttpListenerContext context = listener.GetContext();

            // Traitement de la requête
            HttpListenerRequest request = context.Request;
            string requestPath = request.Url.AbsolutePath;

            if (requestPath.Equals("/hello", StringComparison.OrdinalIgnoreCase))
            {
                // Envoye une réponse avec le contenu "Hello"
                using (StreamWriter writer = new StreamWriter(context.Response.OutputStream))
                {
                    writer.WriteLine("Hello");
                }
                context.Response.StatusCode = 200; // OK
            }
            else
            {
                // Réponse 404 si la requête n'est pas reconnaissable
                context.Response.StatusCode = 404; // Not Found
            }
        }
    }
}
```
