以下是 C++ 多线程程序，用于计算确定的积分方法的近似值（方形法、梯形法和三角法）：
```cpp
#include <iostream>
#include <Windows.h>
#include <cmath>
#include <random>

// 定义IntegerField类，表示一个可以存储小数的整数
class IntegerField {
public:
    int value;

    IntegerField(int v) : value(v) {}
};

// 计算整数部分的 soyaji (由定义分解函数)
int calculateIntegerPart(double x, double a, double b) {
    int result = (int)(a + x * (b - a));
    return result;
}

// 计算浮点部分的 soyaji (由定义 分解函数)
double calculateFractionalPart(double x, double a, double b) {
    double result = x * (b - a);
    result = result - (int)(result);
    return result;
}

//定义一个 函数，用于计算方形法的近似值
void RectangleMethod=IntegerField *integerField, int nThreads, int numTrials) {
    // 本地 Randall 生成器
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(-1.0, 1.0);

    //延迟时间
    int delay = 100;

    //创建一个互斥体
    HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);

    // 创建一个信号量
    HANDLE hSemaphore = CreateSemaphore(NULL, 0, nThreads, NULL);

    // 计算方形法的近似值
    for (int i = 0; i < nThreads; i++) {
        HANDLE hThread = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)rectangleMethodThread, &integerField, 0, NULL);
        Sleep(delay);
        ReleaseSemaphore(hSemaphore, 1, NULL);
    }

    // 等待所有线程完成
    for (int i = 0; i < nThreads; i++) {
        WaitForSingleObject(hSemaphore, INFINITE);
        WaitForSingleObject(hMutex, INFINITE);
        integerField->value += calculateIntegerPart(dis(gen), -1.0, 1.0);
        ReleaseMutex(hMutex);
        Sleep(delay);
    }

    // 释放互斥体和信号量
    ReleaseMutex(hMutex);
    ReleaseSemaphore(hSemaphore, -nThreads, NULL);
    CloseHandle(hMutex);
    CloseHandle(hSemaphore);
}

// 定义一个线程函数，用于计算方形法的近似值
void rectangleMethodThread(LPVOID lpParameter) {
    IntegerField *integerField = (IntegerField *)(lpParameter);

    // 计算方形法的近似值
    double sum = 0.0;
    for (int i = 0; i < numTrials; i++) {
        sum += (calculateFractionalPart((double)i / (numTrials - 1), -1.0, 1.0));
    }

    // 设置互斥体
    WaitForSingleObject(integerField->mutex, INFINITE);
    integerField->value += (int)(sum / numTrials);
    ReleaseMutex(integerField->mutex);
}

int main() {
    const int nThreads = 4;
    const int numTrials = 1000000;

    // 创建一个IntegerField对象
    IntegerField integerField = IntegerField(0);

    //启动 nThreads 个线程
    for (int i = 0; i < nThreads; i++) {
        HANDLE hThread = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)rectangleMethodThread, &integerField, 0, NULL);
        Sleep(1000); // 延迟
    }

    // 等待所有线程完成
    for (int i = 0; i < nThreads; i++) {
        WaitForSingleObject(hThread, INFINITE);
    }

    // 显示计算结果
    std::cout << "Total result: " << integerField.value << std::endl;

    return 0;
}
```
