  for (let i = 0; i < 9; i++) {
    document.getElementById(i.toString()).innerHTML = board[i];
  }
}

// Check if a player has won
function checkWin() {
  for (let i = 0; i < 3; i++) {
    if (board[i * 3] === board[i * 3 + 1] && board[i * 3] === board[i * 3 + 2]) return board[i * 3];
    if (board[i] === board[i * 3] && board[i] === board[i * 3 + 6]) return board[i];
  }
  if (board[0] === board[4] && board[0] === board[8]) return board[0];
  if (board[2] === board[4] && board[2] === board[6]) return board[2];
  return null;
}

// Check if the game is a draw
function checkDraw() {
  return board.every((cell) => cell !== '');
}

// AI's move
function aiMove() {
  if (gameOver) return;

  // Look for a blocking move
