  for (let i = 0; i < 9; i++) {
    if (board[i] === '') {
      board[i] = currentPlayer;
      if (checkWin() === currentPlayer) {
        currentPlayer = 'O';
        return i;
      }
      board[i] = '';
    }
  }

  // If no blocking move, choose a random empty space
  let randomIndex;
  do {
    randomIndex = Math.floor(Math.random() * 9);
  } while (board[randomIndex] !== '');

  return randomIndex;
}

// Player's move
