  if (gameOver) return;
  if (board[index] !== '') return;

  board[index] = currentPlayer;
  updateBoard();
  checkWin() && console.log(`Player ${currentPlayer} wins!`);

  // Switch current player
  currentPlayer = (currentPlayer === 'X') ? 'O' : 'X';
  aiMove();
}

