  public
    procedure RotatePage(PageIndex: Integer; Rotation: Integer);
  end;

implementation

procedure TPDFiumExample.RotatePage(PageIndex: Integer; Rotation: Integer);
var
  i: Integer;
  Page: TPdfPage;
begin
  // Create a new PDF object
  FPdf := TPdf.Create(nil);

  // Open the PDF file
  FPdf.Open('path/to/your/pdf/file.pdf');

  // Get the page at the specified index
  Page := FPdf.GetPage(PageIndex);

  // Rotate the page
